#!/usr/bin/env python3
from __future__ import annotations
import pathlib, sys
ROOT=pathlib.Path(__file__).resolve().parents[1]
def text(p): return (ROOT/p).read_text()
checks=[]
def check(n,c): checks.append((n,bool(c)))
cargo=text('Cargo.toml'); core=text('crates/sparkbridge-core/src/lib.rs'); protocol=text('crates/sparkbridge-protocol/src/lib.rs')
config=text('crates/sparkbridge-config/src/lib.rs'); server=text('apps/sparkbridge-server/src/main.rs'); integrations=text('apps/sparkbridge-server/src/integrations.rs')
integration_crate=text('crates/sparkbridge-integrations/src/lib.rs'); maintenance=text('crates/sparkbridge-maintenance/src/lib.rs')
cli=text('apps/sparkbridge-cli/src/main.rs'); pki=text('apps/sparkbridge-cli/src/pki.rs'); store=text('apps/sparkbridge-server/src/store.rs')
readme=text('README.md'); security=text('SECURITY.md'); user=text('docs/USER_MANUAL.md'); install=text('docs/INSTALLATION_GUIDE.md')
extdoc=text('docs/EXTERNAL_INTEGRATIONS.md'); maintdoc=text('docs/MAINTENANCE.md')
check('workspace version 0.12.0','version = "0.12.0"' in cargo)
check('protocol is 1.10','PROTOCOL_MINOR: u16 = 10' in protocol)
check('schema marker is 9','SCHEMA_VERSION: u32 = 9' in store and 'PRAGMA user_version = 9' in store)
check('integration and maintenance crates are workspace members','crates/sparkbridge-integrations' in cargo and 'crates/sparkbridge-maintenance' in cargo)
check('iteration 11 feature set exists','ITERATION_11_INTEGRATIONS' in core and all(x in core for x in ['McpIntegration','IdeApi','OpenAiCompatibility','OperatorDashboard','BackupRestore','SignedUpdates']))
check('server advertises iteration 11','ITERATION_11_INTEGRATIONS' in server)
check('integration listener has separate bind','integration_bind' in config and 'integration_addr' in server)
check('integration listener requires https public URL','public_integration_url must use https://' in config)
check('integration token path is separate','integration_token_path' in config and 'integration-token' in pki)
check('PKI init creates integration token','Integration bearer token written' in pki)
check('integration auth hashes bearer token','IntegrationAuth' in integration_crate and 'constant_time_eq' in integration_crate)
check('integration listener uses TLS','integration_tls' in server and 'bind_rustls(integration_addr' in server)
check('integration principal is seeded','External Integration Client' in server and 'PrincipalKind::Service' in server)
check('integration principal omits promotion authority','permissions: vec![Permission::Read, Permission::Snapshot, Permission::CandidateCreate, Permission::Execute]' in server)
check('task creation rewrites client principal','request.spec.principal_id=state.config.integration_principal_id.clone()' in integrations)
check('integration task visibility is principal bound','task is owned by another principal' in integrations)
check('MCP intelligence checks workspace read ACL','authorize_snapshot_read' in integrations and 'Permission::Read' in integrations)
check('MCP modern discovery exists','server/discover' in integrations and 'MCP_PROTOCOL_MODERN' in integration_crate)
check('MCP modern revision is 2026-07-28','2026-07-28' in integration_crate)
check('MCP legacy initialize exists','"initialize"' in integrations and 'MCP_PROTOCOL_LEGACY' in integration_crate)
check('MCP tools list/call exist','tools/list' in integrations and 'tools/call' in integrations)
check('MCP exposes durable task tools','sparkbridge.tasks.list' in integrations and 'sparkbridge.tasks.run' in integrations)
check('MCP task execution uses per-task runtime lock','fn task_runtime_lock' in integrations and 'task_runtime_lock(state,task_id)' in integrations and 'lock.lock().await' in integrations)
check('MCP exposes repository search tools','sparkbridge.intelligence.search' in integrations and 'sparkbridge.intelligence.symbols' in integrations)
check('MCP calls are audited','integration.mcp.tool' in integrations)
check('IDE integration task API exists','/api/v1/integrations/tasks' in integrations)
check('integration summary exists','IntegrationSummary' in integrations and '/api/v1/integrations/summary' in integrations)
check('OpenAI models endpoint exists','/v1/models' in integrations and 'openai_models_from_ollama' in integration_crate)
check('OpenAI chat endpoint exists','/v1/chat/completions' in integrations and 'openai_chat_completions' in text('apps/sparkbridge-server/src/inference.rs'))
check('OpenAI integration stays in inference admission path','self.semaphore.clone().acquire_owned()' in text('apps/sparkbridge-server/src/inference.rs'))
check('Ollama compatibility routes exist',all(x in integrations for x in ['/api/tags','/api/ps','/api/generate','/api/chat']))
check('compatibility routes use SparkBridge inference object','state.inference.stream_generate' in integrations and 'state.inference.stream_chat' in integrations)
check('dashboard exists','/dashboard' in integrations and 'sessionStorage' in integrations)
check('dashboard does not embed integration token','integration-token' not in integrations.split('const DASHBOARD_HTML')[1])
check('integration token CLI rotation exists','IntegrationTokenCommand' in cli and 'SPARKBRIDGE_INTEGRATION_TOKEN' in cli)
check('integration status CLI exists','IntegrationsCommand' in cli and '/api/v1/integrations/summary' in cli)
check('backup crate records per-file sha256','BackupManifest' in maintenance and 'sha256' in maintenance)
check('backup preserves Unix file mode where available','unix_mode' in maintenance and 'restore_unix_mode' in maintenance)
check('backup refuses symlink input','backup input may not be a symlink' in maintenance)
check('restore does not overwrite by default','restore target exists' in maintenance and 'overwrite' in maintenance)
check('backup CLI exists','BackupCommand' in cli and 'create_backup' in cli and 'verify_backup' in cli)
check('signed update uses Ed25519','ed25519_dalek' in maintenance and 'verify_signed_update' in maintenance)
check('update validates artifact digest and size','update artifact digest/size mismatch' in maintenance)
check('staged update does not auto-install','stage_verified_update' in maintenance and 'staging_dir' in cli)
check('update CLI exists','UpdateCommand' in cli and 'UpdateCommand::Verify' in cli and 'UpdateCommand::Stage' in cli)
check('CAS GC defaults dry-run','cas_gc.py' in text('docs/MAINTENANCE.md') and "'mode':'delete' if args.delete else 'dry_run'" in text('scripts/cas_gc.py'))
check('CAS GC has age grace period','--min-age-seconds' in text('scripts/cas_gc.py'))
check('CAS GC recursively follows JSON digest references','collect_json' in text('scripts/cas_gc.py') and 'expand(' in text('scripts/cas_gc.py'))
check('Linux installers are packaged',(ROOT/'packaging/linux/install-server.sh').exists() and (ROOT/'packaging/linux/install-executor.sh').exists())
check('macOS LaunchDaemon is packaged',(ROOT/'packaging/macos/com.sparkbridge.executor.plist').exists() and (ROOT/'packaging/macos/install-executor.sh').exists())
check('Windows service installer is packaged',(ROOT/'packaging/windows/install-executor.ps1').exists() and (ROOT/'packaging/windows/uninstall-executor.ps1').exists())
check('manuals are bundled and current','v0.12.0' in user and '1.10' in user and 'v0.12.0' in install and '1.10' in install)
check('external integration guide is bundled','2026-07-28' in extdoc and 'integration-client' in extdoc)
check('maintenance guide is bundled','Ed25519' in maintdoc and 'CAS garbage collection' in maintdoc)
check('security model separates integration trust surface','Integration listener' in security and 'integration-token' in security)
check('security model forbids external promotion shortcut','No integration promotion endpoint' in security)
check('README preserves integration/production layer','MCP' in readme and 'backup/restore' in readme and 'integration' in readme.lower())
check('no automatic promotion remains documented','automatically promote' in readme.lower() or 'automatically promote' in user.lower() or 'auto-promot' in readme.lower())
failed=[n for n,c in checks if not c]
for n,c in checks: print(('PASS' if c else 'FAIL')+': '+n)
if failed:
    print(f'\n{len(failed)} integration/production invariant(s) failed',file=sys.stderr); sys.exit(1)
print(f'\nExternal Integrations + Production Polish audit passed: {len(checks)} invariants')
